// Expanded human-study dilemma catalog on the library page. Everything is drawn from window.LIBRARY_EXPANDED
// (assets/library-expanded-data.js, generated by Cosmos_HumanDilemmas_Expanded/build_site_library.py together with
// data/library_expanded.json); nothing is typed into the page. The Singer section (window.LIBRARY, library.js) is
// separate and unchanged. No network, no storage, no HTML injection. No AI result exists: every item says Not yet tested.
(function () {
  "use strict";
  var X = window.LIBRARY_EXPANDED; if (!X) return;
  function $(id) { return document.getElementById(id); }
  function h(tag, cls, text) { var n = document.createElement(tag); if (cls) n.className = cls; if (text != null) n.textContent = text; return n; }
  function add(p) { for (var i = 1; i < arguments.length; i++) if (arguments[i]) p.appendChild(arguments[i]); return arguments[arguments.length - 1]; }
  function clear(n) { while (n.firstChild) n.removeChild(n.firstChild); return n; }
  function link(href, text) { var a = h("a", null, text); a.href = href; if (/^https?:/.test(href)) a.rel = "noopener"; return a; }
  function dl(box, rows) { rows.forEach(function (r) { if (r[1] == null || r[1] === "") return; add(box, h("dt", null, r[0])); var d = add(box, h("dd")); if (typeof r[1] === "string") d.textContent = r[1]; else add(d, r[1]); }); }

  var SRC = {}; X.sources.forEach(function (s) { SRC[s.source_id] = s; });
  var ITEMS = X.items, BY = {}; ITEMS.forEach(function (it) { BY[it.id] = it; });
  var CLS = { clean_paired: "kind-orig", exploratory: "kind-stress", catalog_only: "kind-none" };
  var st = { src: "all", cls: "all", sub: "all", q: "", sel: null };

  // ---------------------------------------------------------------- intro and sources
  var S1 = X.subset_v1;
  $("x-intro").textContent = X.ai_note + " " + X.human_data_note + " Experiment set v1.1: " + S1.n + " items (" +
    Object.keys(S1.per_source).map(function (k) { return SRC[k].short + " " + S1.per_source[k]; }).join(", ") + "; " +
    S1.per_class.clean_paired + " clean paired, " + S1.per_class.exploratory + " exploratory). " + S1.rule;
  var sb = $("xsources");
  X.sources.forEach(function (s) {
    var c = add(sb, h("article", "card srccard")); c.setAttribute("data-source", s.source_id);
    if (s.public_release_blocked) add(c, h("span", "kind kind-private", X.private_badge));
    add(c, h("h3", null, s.short));
    var p = add(c, h("p")); add(p, document.createTextNode(s.citation + " ")); add(p, link(s.doi_url, s.doi_url));
    var lic = add(c, h("p")); add(lic, document.createTextNode("Licence: ")); add(lic, link(s.licence_url, s.licence_short)); add(lic, document.createTextNode(". " + s.licence_verdict + "."));
    var n = s.counts;
    add(c, h("p", "fine", n.items + " dilemmas: " + n.clean_paired + " clean paired, " + n.exploratory + " exploratory, " + n.catalog_only + " catalog only; " + n.in_subset_v1 + " in experiment set v1.1."));
  });

  // ---------------------------------------------------------------- filters
  var fs = $("xsrc"); add(fs, h("option", null, "All sources")).value = "all";
  X.sources.forEach(function (s) { add(fs, h("option", null, s.short)).value = s.source_id; });
  var fc = $("xclass"); [["all", "All classes"], ["clean_paired", "Clean paired"], ["exploratory", "Exploratory"], ["catalog_only", "Catalog only"]].forEach(function (o) { add(fc, h("option", null, o[1])).value = o[0]; });
  var fu = $("xsub"); [["all", "In or out of the experiment set"], ["in", "In experiment set v1.1"], ["out", "Not in the experiment set"]].forEach(function (o) { add(fu, h("option", null, o[1])).value = o[0]; });
  fs.addEventListener("change", function () { st.src = fs.value; draw(); });
  fc.addEventListener("change", function () { st.cls = fc.value; draw(); });
  fu.addEventListener("change", function () { st.sub = fu.value; draw(); });
  $("xq").addEventListener("input", function () { st.q = $("xq").value.trim().toLowerCase(); draw(); });

  function textOf(it) {
    var t = it.text, parts = [it.id, it.title, SRC[it.source_id].short];
    if (t.mode === "verbatim") parts.push(t.scenario, t.question || "", t.options[0], t.options[1]);
    if (t.mode === "pointer") parts.push(t.description);
    return parts.join(" ").toLowerCase();
  }
  function matches(it) {
    if (st.src !== "all" && it.source_id !== st.src) return false;
    if (st.cls !== "all" && it.class !== st.cls) return false;
    if (st.sub === "in" && !it.in_subset_v1) return false;
    if (st.sub === "out" && it.in_subset_v1) return false;
    if (!st.q) return true;
    var t = textOf(it); return st.q.split(/\s+/).every(function (w) { return t.indexOf(w) >= 0; });
  }
  function draw() {
    var box = clear($("xlist")), shown = ITEMS.filter(matches);
    shown.forEach(function (it) {
      var b = add(box, h("button", "dcard xcard")); b.type = "button";
      b.setAttribute("data-id", it.id); b.setAttribute("data-class", it.class); b.setAttribute("data-source", it.source_id);
      b.setAttribute("data-subset", it.in_subset_v1 ? "in" : "out"); b.setAttribute("aria-pressed", st.sel === it.id ? "true" : "false");
      add(b, h("small", null, it.id + " · " + SRC[it.source_id].short)); add(b, document.createTextNode(it.title));
      var tags = add(b, h("span", "xtags"));
      add(tags, h("span", "kind " + CLS[it.class], it.class_label));
      if (it.in_subset_v1) add(tags, h("span", "kind kind-ours", "In experiment set v1.1"));
      if (it.public_release_blocked) add(tags, h("span", "kind kind-private", "Private"));
      b.addEventListener("click", function () {
        if (it.text.mode === "singer_section") { location.hash = it.text.anchor; return; }
        open(it.id, true);
      });
    });
    $("xcount").textContent = "Showing " + shown.length + " of " + ITEMS.length + " catalog dilemmas";
    $("xempty").hidden = shown.length > 0;
  }

  // ---------------------------------------------------------------- detail
  function open(id, focus) {
    var it = BY[id]; if (!it || it.text.mode === "singer_section") return;
    st.sel = id; draw();
    if (location.hash !== "#x-" + id) history.replaceState(null, "", "#x-" + id);
    $("xdetail").hidden = false;
    var s = SRC[it.source_id], t = it.text;
    $("xd-h").textContent = it.title;
    $("xd-meta").textContent = it.id + " · " + s.short;
    var pv = $("xd-private"); pv.hidden = !it.public_release_blocked; pv.textContent = it.private_badge || "";

    var ob = clear($("xd-orig"));
    if (t.mode === "verbatim") {
      add(ob, h("p", "kind kind-orig", "Original"));
      add(ob, h("h3", null, "As published"));
      add(ob, h("blockquote", "xscn", t.scenario));
      if (t.question) add(ob, h("p", "xq", t.question));
      var opts = add(ob, h("div", "opts"));
      t.options.forEach(function (o, i) { var c = add(opts, h("div", "optc")); add(c, h("span", "cls", "Option " + (i + 1) + ": " + t.option_meanings[i])); add(c, document.createTextNode(o)); });
      add(ob, h("p", "fine", "Where in the source: " + t.location + "."));
    } else {
      add(ob, h("p", "kind kind-none", t.withheld ? "Text withheld · rights not established" : "Catalog only · no text copied"));
      add(ob, h("h3", null, t.withheld ? "Not reproduced" : "Described, not reproduced"));
      if (t.description) add(ob, h("p", "small", "Our description (not the source's words): " + t.description + "."));
      add(ob, h("p", "fine", "Where to find it: " + t.pointer + "."));
      add(ob, h("p", "fine", "Why the text is not copied: " + t.why_not_copied));
    }
    var at = add(ob, h("p", "fine"));
    add(at, document.createTextNode("Source: " + s.citation + " ")); add(at, link(s.doi_url, s.doi_url));
    add(at, document.createTextNode(". Licence: ")); add(at, link(s.licence_url, s.licence_short)); add(at, document.createTextNode(" (" + s.licence_verdict + ")."));

    $("xd-hctx").textContent = X.human_data_note;
    $("xd-human").textContent = (it.human.status === "no_human_data" ? "No human data. " : "") + it.human.summary;

    var cd = clear($("xd-class"));
    var ck = $("xd-ckind"); ck.className = "kind " + CLS[it.class]; ck.textContent = it.class_label;
    dl(cd, [["Class (our coding)", it.class_label + ": " + it.class_reason],
            ["Value-conflict tags", it.value_tags.join(", ")], ["Relationships", it.relationship_tags.join(", ")],
            ["Experiment set v1.1", it.in_subset_v1 ? "In experiment set v1.1. " + it.subset.reason : "Not in the experiment set."],
            ["Versions of the same situation", it.other_versions.length ? it.other_versions.join(", ") + " (at most one version is drawn)" : "None"]]);

    var dr = clear($("xd-draft"));
    if (it.draft) {
      add(dr, h("p", "small muted", "Priority statements (" + it.draft.status + "). Each is written to favour one original option; that option is not a correct answer."));
      it.draft.statements.forEach(function (x, i) { var p = add(dr, h("div", "prio")); add(p, h("span", "k", "Statement favouring option " + (i + 1))); add(p, document.createTextNode("“" + x + "”")); });
      add(dr, h("p", "k", "Adaptations of the presented text"));
      var ul = add(dr, h("ul", "small")); it.draft.adaptations.forEach(function (a) { add(ul, h("li", null, a)); });
      if (it.draft.decisions.length) { add(dr, h("p", "k", "Recorded decisions")); var u3 = add(dr, h("ul", "small")); it.draft.decisions.forEach(function (a) { add(u3, h("li", null, a)); }); }
      if (it.original_task) add(dr, h("p", "small", it.original_task));
      if (it.adapted_note) add(dr, h("p", "small", it.adapted_note));
      if (it.draft.investigator_choices.length) { add(dr, h("p", "k", "Open choices for the investigator")); var u2 = add(dr, h("ul", "small")); it.draft.investigator_choices.forEach(function (a) { add(u2, h("li", null, a)); }); }
    } else {
      add(dr, h("p", "small muted", t.withheld ? "Adaptations and priority statements are not shown in the public version: they paraphrase the withheld text." : it.class === "catalog_only" ? "No adaptation: catalog-only items are never put to an AI." : "No adaptation drafted: this item is not in experiment set v1.1."));
    }
    var ai = clear($("xd-ai")); var cell = add(ai, h("p", "mcell")); cell.setAttribute("data-status", it.ai.status);
    add(cell, h("b", null, "AI result")); add(cell, h("span", "v", "Not yet tested"));
    add(ai, h("p", "fine", X.ai_note));
    if (focus) { $("xd-h").focus(); $("xdetail").scrollIntoView(); }
  }

  draw();
  function fromHash() { var x = location.hash.slice(1); if (x.indexOf("x-") === 0 && BY[x.slice(2)] && x.slice(2) !== st.sel) open(x.slice(2), true); }
  var hid = location.hash.slice(1); if (hid.indexOf("x-") === 0 && BY[hid.slice(2)]) open(hid.slice(2), false);
  window.addEventListener("hashchange", fromHash);
})();
